"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

export default function Home() {
  const [products, setProducts] = useState<any[]>([]);
    const [categories, setCategories] = useState<any[]>([]);
      const [settings, setSettings] = useState<any>(null);
        const [loading, setLoading] = useState(true);
          const [selectedCategory, setSelectedCategory] = useState<string>("الكل");

            // حالات العداد التنازلي
              const [timeLeft, setTimeLeft] = useState({ hours: 0, minutes: 0, seconds: 0 });

                useEffect(() => {
                    // جلب البيانات
                        Promise.all([
                              fetch("/api/products").then(res => res.json()),
                                    fetch("/api/categories").then(res => res.json()),
                                          fetch("/api/settings").then(res => res.json())
                                              ])
                                                    .then(([productsData, categoriesData, settingsData]) => {
                                                            setProducts(productsData);
                                                                    setCategories(categoriesData);
                                                                            setSettings(settingsData);
                                                                                    setLoading(false);
                                                                                          })
                                                                                                .catch((err) => {
                                                                                                        console.error("Error fetching data:", err);
                                                                                                                setLoading(false);
                                                                                                                      });
                                                                                                                        }, []);

                                                                                                                          // مؤقت العداد التنازلي
                                                                                                                            useEffect(() => {
                                                                                                                                const calculateTimeLeft = () => {
                                                                                                                                      const now = new Date();
                                                                                                                                            const target = new Date();
                                                                                                                                                  target.setHours(24, 0, 0, 0); 
                                                                                                                                                        const difference = target.getTime() - now.getTime();

                                                                                                                                                              if (difference > 0) {
                                                                                                                                                                      setTimeLeft({
                                                                                                                                                                                hours: Math.floor((difference / (1000 * 60 * 60)) % 24),
                                                                                                                                                                                          minutes: Math.floor((difference / 1000 / 60) % 60),
                                                                                                                                                                                                    seconds: Math.floor((difference / 1000) % 60)
                                                                                                                                                                                                            });
                                                                                                                                                                                                                  }
                                                                                                                                                                                                                      };

                                                                                                                                                                                                                          calculateTimeLeft();
                                                                                                                                                                                                                              const timer = setInterval(calculateTimeLeft, 1000);
                                                                                                                                                                                                                                  return () => clearInterval(timer);
                                                                                                                                                                                                                                    }, []);

                                                                                                                                                                                                                                      const filteredProducts = selectedCategory === "الكل" 
                                                                                                                                                                                                                                          ? products 
                                                                                                                                                                                                                                              : products.filter(p => p.category === selectedCategory);

                                                                                                                                                                                                                                                if (loading) return <p className="text-center mt-20 text-lg font-bold">جاري تحميل المتجر...</p>;

                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                      <main className="max-w-7xl mx-auto p-4 bg-gray-50 min-h-screen" dir="rtl">
                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                  {/* البانر الإعلاني مع العداد وزر تسوق الآن */}
                                                                                                                                                                                                                                                                        <div className="w-full bg-gradient-to-l from-red-600 via-orange-500 to-yellow-400 rounded-xl mb-6 p-6 sm:p-10 flex flex-col md:flex-row items-center justify-between text-white shadow-md relative overflow-hidden">
                                                                                                                                                                                                                                                                                <div className="relative z-10 text-center md:text-right mb-4 md:mb-0">
                                                                                                                                                                                                                                                                                          <h1 className="text-3xl sm:text-5xl font-black mb-2">{settings?.heroTitle || "تخفيضات الميجا سيل!"}</h1>
                                                                                                                                                                                                                                                                                                    <p className="text-sm sm:text-lg opacity-95 font-medium">{settings?.heroSubtitle || "خصومات تصل لـ 70% | توصيل سريع"}</p>
                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                        {/* ✅ زر تسوق الآن مربوط بقسم المنتجات */}
                                                                                                                                                                                                                                                                                                                                  <a href="#products-section" className="mt-4 inline-block bg-white text-red-600 font-bold px-8 py-3 rounded-full hover:bg-gray-100 transition-colors shadow-lg cursor-pointer">
                                                                                                                                                                                                                                                                                                                                              {settings?.heroBtnText || "تسوق الآن"}
                                                                                                                                                                                                                                                                                                                                                        </a>
                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                        {/* العداد التنازلي */}
                                                                                                                                                                                                                                                                                                                                                                                <div className="relative z-10 flex flex-col items-center bg-white/20 backdrop-blur-sm p-4 rounded-xl border border-white/30">
                                                                                                                                                                                                                                                                                                                                                                                          <p className="text-sm font-bold mb-2">ينتهي العرض بعد:</p>
                                                                                                                                                                                                                                                                                                                                                                                                    <div className="flex gap-2 text-center" dir="ltr">
                                                                                                                                                                                                                                                                                                                                                                                                                <div className="bg-white text-red-600 rounded-lg p-2 w-14 shadow-md">
                                                                                                                                                                                                                                                                                                                                                                                                                              <span className="text-2xl font-black">{timeLeft.seconds}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="block text-[10px] font-bold uppercase mt-1">ثانية</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="bg-white text-red-600 rounded-lg p-2 w-14 shadow-md">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span className="text-2xl font-black">{timeLeft.minutes}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span className="block text-[10px] font-bold uppercase mt-1">دقيقة</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="bg-white text-red-600 rounded-lg p-2 w-14 shadow-md">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <span className="text-2xl font-black">{timeLeft.hours}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className="block text-[10px] font-bold uppercase mt-1">ساعة</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <span className="text-7xl sm:text-9xl opacity-20 absolute -left-4 -bottom-4 pointer-events-none">🛍️</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div id="products-section" className="flex flex-col md:flex-row gap-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/* القائمة الجانبية للأقسام */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <aside className="w-full md:w-64 shrink-0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 sticky top-24">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h3 className="font-bold text-gray-800 mb-4 border-b pb-2 flex items-center gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span>☰</span> كل الأقسام
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <ul className="flex flex-row md:flex-col overflow-x-auto md:overflow-x-visible gap-2 pb-2 md:pb-0 scrollbar-hide">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <li className="shrink-0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onClick={() => setSelectedCategory("الكل")}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            className={`w-full text-right px-4 py-2 rounded-lg text-sm font-semibold transition-colors whitespace-nowrap ${selectedCategory === "الكل" ? "bg-red-50 text-red-600 border-r-2 border-red-600 md:border-r-0 md:border-l-2 md:border-red-600" : "text-gray-700 hover:bg-gray-50"}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              كل المنتجات
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </li>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {categories.map((cat) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <li key={cat.id} className="shrink-0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onClick={() => setSelectedCategory(cat.name)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className={`w-full text-right px-4 py-2 rounded-lg text-sm font-semibold transition-colors whitespace-nowrap ${selectedCategory === cat.name ? "bg-red-50 text-red-600 border-r-2 border-red-600 md:border-r-0 md:border-l-2 md:border-red-600" : "text-gray-700 hover:bg-gray-50"}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {cat.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </li>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </ul>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </aside>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {/* شبكة المنتجات */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="flex items-center justify-between mb-4 bg-white p-3 rounded-lg shadow-sm border border-gray-100">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <h2 className="text-lg font-bold text-gray-800 border-r-4 border-red-500 pr-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {selectedCategory === "الكل" ? "توصيات لك" : `قسم: ${selectedCategory}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className="text-sm text-gray-500 font-bold">{filteredProducts.length} منتج</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {filteredProducts.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="text-center py-20 bg-white rounded-lg shadow-sm">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="text-5xl mb-4">📦</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <h2 className="text-xl font-bold text-gray-800 mb-2">ما في منتجات بهالقسم حالياً.</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3 md:gap-4 animate-fade-in-up">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {filteredProducts.map((product) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const isOutOfStock = product.stock <= 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Link key={product.id} href={`/product?slug=${product.slug}`} className="group block bg-white rounded-lg overflow-hidden hover:shadow-xl transition-all duration-300 border border-gray-100 relative">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="relative w-full h-40 sm:h-48 bg-gray-50 overflow-hidden">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {product.imageUrl && <img src={product.imageUrl} alt={product.name} className={`w-full h-full object-cover group-hover:scale-105 transition-transform duration-500 ${isOutOfStock ? 'opacity-50' : ''}`} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="absolute top-0 left-0 bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-br-lg z-10 shadow-sm">خصم 15%</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {isOutOfStock && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="absolute inset-0 bg-black bg-opacity-40 flex items-center justify-center z-10">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <span className="bg-red-600 text-white px-3 py-1 rounded-full text-xs font-bold">نفدت الكمية</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="p-2 sm:p-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h2 className="text-xs sm:text-sm font-medium text-gray-800 line-clamp-2 leading-tight h-9">{product.name}</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="mt-1 flex items-center gap-1"><span className="text-orange-400 text-[10px]">★★★★★</span><span className="text-gray-400 text-[10px]">(2.5k)</span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="mt-1 flex items-baseline gap-1 flex-wrap">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="text-base sm:text-lg font-black text-red-600">${(product.price / 100).toFixed(2)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="text-[10px] text-gray-400 line-through">${((product.price * 1.15) / 100).toFixed(2)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="mt-1 flex items-center justify-between"><p className="text-[10px] text-green-600 font-bold bg-green-50 px-1 rounded">شحن مجاني</p><p className="text-[10px] text-gray-400">تم البيع 100+</p></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }